export const routeSlug=value=>String(value).toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
export function parsePageRoute(pathname,search=''){try{const parts=pathname.split('/').filter(Boolean).map(decodeURIComponent),floor=new URLSearchParams(search).get('floor');if(!parts.length)return {type:'warehouses'};if(parts.length===1&&parts[0]==='login')return {type:'login',next:new URLSearchParams(search).get('next')};if(parts[0]!=='warehouses')return {type:'notfound'};if(parts.length===1)return {type:'warehouses'};const warehouseId=parts[1];if(!/^[A-Za-z0-9_:-]{1,150}$/.test(warehouseId))return {type:'notfound'};if(parts.length===2)return {type:'warehouse',warehouseId,page:'overview',view:'dashboard',floor};if(parts[2]==='editor'){const mode={foundation:'foundation',sections:'section',racks:'racks',customers:'customers'}[parts[3]||'foundation'];return mode&&parts.length<=4?{type:'warehouse',warehouseId,page:'editor',mode,floor}:{type:'notfound'};}if(parts[2]==='overview'){const view={dashboard:'dashboard',tables:'tables','raw-data':'excel'}[parts[3]||'dashboard'];if(view==='dashboard'&&parts.length<=4)return {type:'warehouse',warehouseId,page:'overview',view,floor};if(view==='tables'&&parts.length<=5&&['area','customer','templates'].includes(parts[4]||'area'))return {type:'warehouse',warehouseId,page:'overview',view,table:parts[4]||'area',floor};if(view==='excel'&&parts.length<=5)return {type:'warehouse',warehouseId,page:'overview',view,sheet:parts[4]||'floors',floor};}return {type:'notfound'};}catch{return {type:'notfound'}}}
export function pageRoutePath(route){if(route.type==='login')return '/login'+(route.next?'?next='+encodeURIComponent(route.next):'');if(route.type!=='warehouse')return '/warehouses';const base='/warehouses/'+encodeURIComponent(route.warehouseId);let path=route.page==='editor'?base+'/editor'+(route.mode&&route.mode!=='foundation'?'/'+({section:'sections',racks:'racks',customers:'customers'}[route.mode]||''): ''):base+'/overview/'+(route.view==='tables'?'tables/'+(route.table||'area'):route.view==='excel'?'raw-data/'+(route.sheet||'floors'):'dashboard');if(route.floor&&route.floor!=='all')path+='?floor='+encodeURIComponent(route.floor);return path;}
export function safeNextPath(value){if(typeof value!=='string'||!value.startsWith('/')||value.startsWith('//')||value.includes('\\'))return '/warehouses';const url=new URL(value,'https://wsms.invalid');const route=parsePageRoute(url.pathname,url.search);return ['warehouse','warehouses'].includes(route.type)?url.pathname+url.search:'/warehouses';}
